import sys

class BankAccount:
    def __init__(self, account_number, balance):
        self.account_number = account_number
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount
        print(self.balance)

    def withdraw(self, amount):
        if amount > self.balance:
            print("Insufficient Balance")
        else:
            self.balance -= amount
            print(self.balance)

def solve():
    data = [line.rstrip('\n') for line in sys.stdin]
    if len(data) < 4:
        return
    acc_num = data[0].strip()
    try:
        bal = int(data[1].strip())
    except ValueError:
        bal = float(data[1].strip())
    operation = data[2].strip().lower()
    try:
        amt = int(data[3].strip())
    except ValueError:
        amt = float(data[3].strip())

    account = BankAccount(acc_num, bal)

    if operation == "deposit":
        account.deposit(amt)
    elif operation == "withdraw":
        account.withdraw(amt)

if __name__ == "__main__":
    solve()
